-- ============================================================
-- CLEAN reference schema (PostgreSQL) for: Accounts, Selling, Buying, Stock, Subcontracting, Setup
-- Surrogate bigint PKs, real FKs, one child table per parent field.
-- Tables referenced from outside this scope are emitted as stubs at the end.
-- Load this file first, then clean_02_constraints.sql.
-- ============================================================

-- Account (tree-master)
CREATE TABLE account (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  account_name varchar(140) NOT NULL,
  account_number varchar(140),
  is_group smallint NOT NULL DEFAULT 0,
  company_id bigint NOT NULL,   -- -> Company
  root_type varchar(140),   -- enum: Asset | Liability | Income | Expense | Equity
  report_type varchar(140),   -- enum: Balance Sheet | Profit and Loss
  account_currency_id bigint,   -- -> Currency
  parent_account_id bigint NOT NULL,   -- -> Account
  account_type varchar(140),   -- enum: Accumulated Depreciation | Asset Received But Not Billed | Bank | Cash | Chargeable | Capital Work in Progress
  tax_rate numeric(21,9) DEFAULT 0,
  freeze_account varchar(140),   -- enum: No | Yes
  balance_must_be varchar(140),   -- enum: Debit | Credit
  lft integer DEFAULT 0,
  rgt integer DEFAULT 0,
  old_parent varchar(140),
  include_in_gross smallint NOT NULL DEFAULT 0,
  disabled smallint NOT NULL DEFAULT 0,
  account_category_id bigint,   -- -> Account Category
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Account Category (master)
CREATE TABLE account_category (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  account_category_name varchar(140) NOT NULL,
  description text,
  root_type varchar(140),   -- enum: Asset | Liability | Income | Expense | Equity
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Account Closing Balance (transaction)
CREATE TABLE account_closing_balance (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  closing_date date,
  account_id bigint,   -- -> Account
  cost_center_id bigint,   -- -> Cost Center
  debit numeric(21,9) DEFAULT 0,
  credit numeric(21,9) DEFAULT 0,
  account_currency_id bigint,   -- -> Currency
  debit_in_account_currency numeric(21,9) DEFAULT 0,
  credit_in_account_currency numeric(21,9) DEFAULT 0,
  project_id bigint,   -- -> Project
  company_id bigint,   -- -> Company
  finance_book_id bigint,   -- -> Finance Book
  period_closing_voucher_id bigint,   -- -> Period Closing Voucher
  is_period_closing_voucher_entry smallint NOT NULL DEFAULT 0,
  debit_in_reporting_currency numeric(21,9) DEFAULT 0,
  credit_in_reporting_currency numeric(21,9) DEFAULT 0,
  reporting_currency_exchange_rate numeric(21,9) DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Accounting Dimension (master)
CREATE TABLE accounting_dimension (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  label varchar(140),
  fieldname varchar(140),
  document_type_id bigint NOT NULL,   -- -> DocType
  disabled smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Accounting Dimension.dimension_defaults line items -> Accounting Dimension Detail
CREATE TABLE accounting_dimension_dimension_defaults (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  accounting_dimension_id bigint NOT NULL,   -- parent -> Accounting Dimension
  line_no integer NOT NULL,   -- was ERPNext `idx`
  company_id bigint,   -- -> Company
  reference_document_id bigint,   -- -> DocType
  default_dimension varchar(140),   -- polymorphic: target doctype in reference_document
  mandatory_for_bs smallint NOT NULL DEFAULT 0,
  mandatory_for_pl smallint NOT NULL DEFAULT 0,
  automatically_post_balancing_accounting_entry smallint NOT NULL DEFAULT 0,
  offsetting_account_id bigint,   -- -> Account
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Accounting Dimension Filter (master)
CREATE TABLE accounting_dimension_filter (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  accounting_dimension varchar(140) NOT NULL,
  allow_or_restrict varchar(140) NOT NULL,   -- enum: Allow | Restrict
  disabled smallint NOT NULL DEFAULT 0,
  company_id bigint NOT NULL,   -- -> Company
  apply_restriction_on_values smallint NOT NULL DEFAULT 1,
  fieldname varchar(140),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Accounting Dimension Filter.accounts line items -> Applicable On Account
CREATE TABLE accounting_dimension_filter_accounts (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  accounting_dimension_filter_id bigint NOT NULL,   -- parent -> Accounting Dimension Filter
  line_no integer NOT NULL,   -- was ERPNext `idx`
  applicable_on_account_id bigint NOT NULL,   -- -> Account
  is_mandatory smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Accounting Dimension Filter.dimensions line items -> Allowed Dimension
CREATE TABLE accounting_dimension_filter_dimensions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  accounting_dimension_filter_id bigint NOT NULL,   -- parent -> Accounting Dimension Filter
  line_no integer NOT NULL,   -- was ERPNext `idx`
  accounting_dimension_id bigint,   -- -> DocType
  dimension_value varchar(140),   -- polymorphic: target doctype in accounting_dimension
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Accounting Period (master)
CREATE TABLE accounting_period (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  period_name varchar(140) NOT NULL,
  start_date date NOT NULL,
  end_date date NOT NULL,
  company_id bigint NOT NULL,   -- -> Company
  disabled smallint NOT NULL DEFAULT 0,
  exempted_role_id bigint,   -- -> Role
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Accounting Period.closed_documents line items -> Closed Document
CREATE TABLE accounting_period_closed_documents (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  accounting_period_id bigint NOT NULL,   -- parent -> Accounting Period
  line_no integer NOT NULL,   -- was ERPNext `idx`
  document_type_id bigint NOT NULL,   -- -> DocType
  closed smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Advance Payment Ledger Entry (transaction)
CREATE TABLE advance_payment_ledger_entry (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  voucher_type_id bigint,   -- -> DocType
  voucher_no varchar(140),   -- polymorphic: target doctype in voucher_type
  against_voucher_type_id bigint,   -- -> DocType
  against_voucher_no varchar(140),   -- polymorphic: target doctype in against_voucher_type
  amount numeric(21,9) DEFAULT 0,
  currency_id bigint,   -- -> Currency
  event varchar(140),
  company_id bigint,   -- -> Company
  delinked smallint NOT NULL DEFAULT 0,
  base_amount numeric(21,9) DEFAULT 0,
  exchange_rate numeric(21,9) DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Authorization Rule (master)
CREATE TABLE authorization_rule (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  transaction varchar(140) NOT NULL,   -- enum: Sales Order | Purchase Order | Quotation | Delivery Note | Sales Invoice | Purchase Invoice
  based_on varchar(140) NOT NULL,   -- enum: Grand Total | Average Discount | Customerwise Discount | Itemwise Discount | Item Group wise Discount | Not Applicable
  customer_or_item varchar(140),   -- enum: Customer | Item | Item Group
  master_name varchar(140),   -- polymorphic: target doctype in customer_or_item
  company_id bigint,   -- -> Company
  value numeric(21,9) DEFAULT 0,
  system_role_id bigint,   -- -> Role
  to_emp_id bigint,   -- -> Employee
  system_user_id bigint,   -- -> User
  to_designation_id bigint,   -- -> Designation
  approving_role_id bigint,   -- -> Role
  approving_user_id bigint,   -- -> User
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Bank (master)
CREATE TABLE bank (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  bank_name varchar(140) NOT NULL,
  swift_number varchar(140),
  website varchar(140),
  plaid_access_token varchar(140),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Bank Account (master)
CREATE TABLE bank_account (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  account_name varchar(140) NOT NULL,
  account_id bigint,   -- -> Account
  bank_id bigint NOT NULL,   -- -> Bank
  account_type_id bigint,   -- -> Bank Account Type
  account_subtype_id bigint,   -- -> Bank Account Subtype
  is_default smallint NOT NULL DEFAULT 0,
  is_company_account smallint NOT NULL DEFAULT 0,
  company_id bigint,   -- -> Company
  party_type_id bigint,   -- -> DocType
  party varchar(140),   -- polymorphic: target doctype in party_type
  iban varchar(140),
  bank_account_no varchar(140),
  statement_password text,
  integration_id varchar(140),
  last_integration_date date,
  mask varchar(140),
  branch_code varchar(140),
  disabled smallint NOT NULL DEFAULT 0,
  is_credit_card smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Bank Account Balance (master)
CREATE TABLE bank_account_balance (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  bank_account_id bigint NOT NULL,   -- -> Bank Account
  date date NOT NULL,
  balance numeric(21,9) NOT NULL DEFAULT 0,
  company_id bigint,   -- -> Company
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Bank Account Subtype (master)
CREATE TABLE bank_account_subtype (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  account_subtype varchar(140),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Bank Account Type (master)
CREATE TABLE bank_account_type (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  account_type varchar(140),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Bank.bank_transaction_mapping line items -> Bank Transaction Mapping
CREATE TABLE bank_bank_transaction_mapping (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  bank_id bigint NOT NULL,   -- parent -> Bank
  line_no integer NOT NULL,   -- was ERPNext `idx`
  bank_transaction_field varchar(140) NOT NULL,
  file_field varchar(140) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Bank Guarantee (transaction)
CREATE TABLE bank_guarantee (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  bg_type varchar(140) NOT NULL,   -- enum: Receiving | Providing
  reference_doctype_id bigint,   -- -> DocType
  reference_docname varchar(140),   -- polymorphic: target doctype in reference_doctype
  customer_id bigint,   -- -> Customer
  supplier_id bigint,   -- -> Supplier
  project_id bigint,   -- -> Project
  amount numeric(21,9) NOT NULL DEFAULT 0,
  start_date date NOT NULL,
  validity integer DEFAULT 0,
  end_date date,
  bank_id bigint,   -- -> Bank
  bank_account_id bigint,   -- -> Bank Account
  account_id bigint,   -- -> Account
  bank_account_no varchar(140),
  iban varchar(140),
  branch_code varchar(140),
  swift_number varchar(140),
  more_information text,
  bank_guarantee_number varchar(140),
  name_of_beneficiary varchar(140),
  margin_money numeric(21,9) DEFAULT 0,
  charges numeric(21,9) DEFAULT 0,
  fixed_deposit_number varchar(140),
  amended_from_id bigint,   -- -> Bank Guarantee
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Bank Statement Import (master)
CREATE TABLE bank_statement_import (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  company_id bigint NOT NULL,   -- -> Company
  bank_account_id bigint NOT NULL,   -- -> Bank Account
  bank_id bigint,   -- -> Bank
  import_file text,
  template_options text,
  status varchar(140),   -- enum: Pending | Success | Partial Success | Error
  template_warnings text,
  show_failed_logs smallint NOT NULL DEFAULT 0,
  google_sheets_url varchar(140),
  reference_doctype_id bigint NOT NULL,   -- -> DocType
  import_type varchar(140) NOT NULL,   -- enum: Insert New Records | Update Existing Records
  submit_after_import smallint NOT NULL DEFAULT 1,
  mute_emails smallint NOT NULL DEFAULT 1,
  custom_delimiters smallint NOT NULL DEFAULT 0,
  delimiter_options varchar(140),
  use_csv_sniffer smallint NOT NULL DEFAULT 0,
  import_mt940_fromat smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Bank Statement Import Log (master)
CREATE TABLE bank_statement_import_log (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  bank_account_id bigint NOT NULL,   -- -> Bank Account
  number_of_transactions integer DEFAULT 0,
  closing_balance numeric(21,9) DEFAULT 0,
  start_date date,
  end_date date,
  file text NOT NULL,
  detected_date_format varchar(140),
  detected_amount_format varchar(140),   -- enum: Separate columns for withdrawal and deposit | Amount column has "CR"/"DR" values | Amount column has positive/negative values | Transaction type column has "CR"/"DR" values | Transaction type column has "Deposit"/"Withdrawal" values | Transaction type column has "C"/"D" values
  detected_header_index integer DEFAULT 0,
  detected_transaction_starting_index integer DEFAULT 0,
  detected_transaction_ending_index integer DEFAULT 0,
  pdf_tables jsonb,
  status varchar(140),   -- enum: Not Started | Completed
  currency_id bigint,   -- -> Currency
  total_debits numeric(21,9) DEFAULT 0,
  total_credits numeric(21,9) DEFAULT 0,
  total_debit_transactions integer DEFAULT 0,
  total_credit_transactions integer DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Bank Statement Import Log.column_mapping line items -> Bank Statement Import Log Column Map
CREATE TABLE bank_statement_import_log_column_mapping (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  bank_statement_import_log_id bigint NOT NULL,   -- parent -> Bank Statement Import Log
  line_no integer NOT NULL,   -- was ERPNext `idx`
  header_text varchar(140) NOT NULL,
  maps_to varchar(140) NOT NULL,   -- enum: Do not import | Date | Withdrawal | Deposit | Amount | Description
  index integer NOT NULL DEFAULT 0,
  variable varchar(140),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Bank Transaction (transaction)
CREATE TABLE bank_transaction (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  naming_series varchar(140) NOT NULL,   -- enum: ACC-BTN-.YYYY.-
  date date,
  status varchar(140),   -- enum: Pending | Settled | Unreconciled | Reconciled | Cancelled
  bank_account_id bigint,   -- -> Bank Account
  company_id bigint,   -- -> Company
  currency_id bigint,   -- -> Currency
  description text,
  reference_number text,
  transaction_id varchar(140),
  allocated_amount numeric(21,9) DEFAULT 0,
  amended_from_id bigint,   -- -> Bank Transaction
  unallocated_amount numeric(21,9) DEFAULT 0,
  party_type_id bigint,   -- -> DocType
  party varchar(140),   -- polymorphic: target doctype in party_type
  deposit numeric(21,9) DEFAULT 0,
  withdrawal numeric(21,9) DEFAULT 0,
  transaction_type varchar(140),
  bank_party_name varchar(140),
  bank_party_iban varchar(140),
  bank_party_account_number varchar(140),
  included_fee numeric(21,9) DEFAULT 0,
  excluded_fee numeric(21,9) DEFAULT 0,
  is_rule_evaluated smallint NOT NULL DEFAULT 0,
  matched_transaction_rule_id bigint,   -- -> Bank Transaction Rule
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Bank Transaction.payment_entries line items -> Bank Transaction Payments
CREATE TABLE bank_transaction_payment_entries (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  bank_transaction_id bigint NOT NULL,   -- parent -> Bank Transaction
  line_no integer NOT NULL,   -- was ERPNext `idx`
  payment_document_id bigint NOT NULL,   -- -> DocType
  payment_entry varchar(140) NOT NULL,   -- polymorphic: target doctype in payment_document
  allocated_amount numeric(21,9) NOT NULL DEFAULT 0,
  clearance_date date,
  reconciliation_type varchar(140),   -- enum: Matched | Voucher Created
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Bank Transaction Rule (master)
CREATE TABLE bank_transaction_rule (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  rule_name varchar(140) NOT NULL,
  transaction_type varchar(140) NOT NULL,   -- enum: Any | Withdrawal | Deposit
  min_amount numeric(21,9) DEFAULT 0,
  max_amount numeric(21,9) DEFAULT 0,
  rule_description text,
  classify_as varchar(140) NOT NULL,   -- enum: Bank Entry | Payment Entry | Transfer
  account_id bigint,   -- -> Account
  party_type_id bigint,   -- -> DocType
  party varchar(140),   -- polymorphic: target doctype in party_type
  priority integer NOT NULL DEFAULT 0,
  company_id bigint NOT NULL,   -- -> Company
  bank_entry_type varchar(140),   -- enum: Single Account | Multiple Accounts
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Bank Transaction Rule.accounts line items -> Bank Transaction Rule Accounts
CREATE TABLE bank_transaction_rule_accounts (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  bank_transaction_rule_id bigint NOT NULL,   -- parent -> Bank Transaction Rule
  line_no integer NOT NULL,   -- was ERPNext `idx`
  account_id bigint NOT NULL,   -- -> Account
  party_type_id bigint,   -- -> Party Type
  party varchar(140),   -- polymorphic: target doctype in party_type
  debit varchar(140),
  credit varchar(140),
  user_remark text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Bank Transaction Rule.description_rules line items -> Bank Transaction Rule Description Conditions
CREATE TABLE bank_transaction_rule_description_rules (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  bank_transaction_rule_id bigint NOT NULL,   -- parent -> Bank Transaction Rule
  line_no integer NOT NULL,   -- was ERPNext `idx`
  "check" varchar(140) NOT NULL,   -- enum: Contains | Starts With | Ends With | Regex
  value text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Batch (master)
CREATE TABLE batch (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  disabled smallint NOT NULL DEFAULT 0,
  batch_id varchar(140) NOT NULL,
  item_id bigint NOT NULL,   -- -> Item
  image text,
  parent_batch_id bigint,   -- -> Batch
  manufacturing_date date,
  expiry_date date,
  supplier_id bigint,   -- -> Supplier
  reference_doctype_id bigint,   -- -> DocType
  reference_name varchar(140),   -- polymorphic: target doctype in reference_doctype
  description text,
  item_name varchar(140),   -- denormalised from item.item_name
  batch_qty numeric(21,9) DEFAULT 0,
  stock_uom_id bigint,   -- -> UOM
  qty_to_produce numeric(21,9) DEFAULT 0,
  produced_qty numeric(21,9) DEFAULT 0,
  use_batchwise_valuation smallint NOT NULL DEFAULT 0,
  allow_negative_stock_for_batch smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Bin (master)
CREATE TABLE bin (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  warehouse_id bigint NOT NULL,   -- -> Warehouse
  item_code_id bigint NOT NULL,   -- -> Item
  reserved_qty numeric(21,9) DEFAULT 0,
  actual_qty numeric(21,9) DEFAULT 0,
  ordered_qty numeric(21,9) DEFAULT 0,
  indented_qty numeric(21,9) DEFAULT 0,
  planned_qty numeric(21,9) DEFAULT 0,
  projected_qty numeric(21,9) DEFAULT 0,
  reserved_qty_for_production numeric(21,9) DEFAULT 0,
  reserved_qty_for_sub_contract numeric(21,9) DEFAULT 0,
  stock_uom_id bigint,   -- -> UOM
  company_id bigint,   -- -> Company
  valuation_rate numeric(21,9) DEFAULT 0,
  stock_value numeric(21,9) DEFAULT 0,
  reserved_qty_for_production_plan numeric(21,9) DEFAULT 0,
  reserved_stock numeric(21,9) DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Bisect Nodes (master)
CREATE TABLE bisect_nodes (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  root_id bigint,   -- -> Bisect Nodes
  left_child_id bigint,   -- -> Bisect Nodes
  right_child_id bigint,   -- -> Bisect Nodes
  period_from_date timestamp,
  period_to_date timestamp,
  difference numeric(21,9) DEFAULT 0,
  balance_sheet_summary numeric(21,9) DEFAULT 0,
  profit_loss_summary numeric(21,9) DEFAULT 0,
  generated smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Branch (master)
CREATE TABLE branch (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  branch varchar(140) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Brand (master)
CREATE TABLE brand (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  brand varchar(140) NOT NULL,
  description text,
  image text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Brand.brand_defaults line items -> Item Default
CREATE TABLE brand_brand_defaults (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  brand_id bigint NOT NULL,   -- parent -> Brand
  line_no integer NOT NULL,   -- was ERPNext `idx`
  company_id bigint NOT NULL,   -- -> Company
  default_warehouse_id bigint,   -- -> Warehouse
  default_price_list_id bigint,   -- -> Price List
  default_discount_account_id bigint,   -- -> Account
  default_inventory_account_id bigint,   -- -> Account
  inventory_account_currency_id bigint,   -- -> Currency
  buying_cost_center_id bigint,   -- -> Cost Center
  default_supplier_id bigint,   -- -> Supplier
  expense_account_id bigint,   -- -> Account
  default_provisional_account_id bigint,   -- -> Account
  purchase_expense_account_id bigint,   -- -> Account
  purchase_expense_contra_account_id bigint,   -- -> Account
  expenses_added_to_stock_account_id bigint,   -- -> Account
  expenses_added_to_stock_contra_account_id bigint,   -- -> Account
  purchase_price_variance_account_id bigint,   -- -> Account
  manufacturing_variance_account_id bigint,   -- -> Account
  selling_cost_center_id bigint,   -- -> Cost Center
  income_account_id bigint,   -- -> Account
  default_cogs_account_id bigint,   -- -> Account
  deferred_expense_account_id bigint,   -- -> Account
  deferred_revenue_account_id bigint,   -- -> Account
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Budget (transaction)
CREATE TABLE budget (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  budget_against varchar(140) NOT NULL,   -- enum: Cost Center | Project
  company_id bigint NOT NULL,   -- -> Company
  cost_center_id bigint,   -- -> Cost Center
  project_id bigint,   -- -> Project
  amended_from_id bigint,   -- -> Budget
  applicable_on_material_request smallint NOT NULL DEFAULT 0,
  action_if_annual_budget_exceeded_on_mr varchar(140),   -- enum: Stop | Warn | Ignore
  action_if_accumulated_monthly_budget_exceeded_on_mr varchar(140),   -- enum: Stop | Warn | Ignore
  applicable_on_purchase_order smallint NOT NULL DEFAULT 0,
  action_if_annual_budget_exceeded_on_po varchar(140),   -- enum: Stop | Warn | Ignore
  action_if_accumulated_monthly_budget_exceeded_on_po varchar(140),   -- enum: Stop | Warn | Ignore
  applicable_on_booking_actual_expenses smallint NOT NULL DEFAULT 0,
  action_if_annual_budget_exceeded varchar(140),   -- enum: Stop | Warn | Ignore
  action_if_accumulated_monthly_budget_exceeded varchar(140),   -- enum: Stop | Warn | Ignore
  naming_series varchar(140) NOT NULL,   -- enum: BUDGET-.########
  applicable_on_cumulative_expense smallint NOT NULL DEFAULT 0,
  action_if_annual_exceeded_on_cumulative_expense varchar(140),   -- enum: Stop | Warn | Ignore
  action_if_accumulated_monthly_exceeded_on_cumulative_expense varchar(140),   -- enum: Stop | Warn | Ignore
  account_id bigint NOT NULL,   -- -> Account
  budget_amount numeric(21,9) NOT NULL DEFAULT 0,
  revision_of varchar(140),
  distribute_equally smallint NOT NULL DEFAULT 1,
  from_fiscal_year_id bigint NOT NULL,   -- -> Fiscal Year
  to_fiscal_year_id bigint NOT NULL,   -- -> Fiscal Year
  budget_start_date date,
  budget_end_date date,
  distribution_frequency varchar(140) NOT NULL,   -- enum: Monthly | Quarterly | Half-Yearly | Yearly
  budget_distribution_total numeric(21,9) DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Budget.budget_distribution line items -> Budget Distribution
CREATE TABLE budget_budget_distribution (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  budget_id bigint NOT NULL,   -- parent -> Budget
  line_no integer NOT NULL,   -- was ERPNext `idx`
  start_date date NOT NULL,
  end_date date NOT NULL,
  amount numeric(21,9) NOT NULL DEFAULT 0,
  percent numeric(21,9) NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Cashier Closing (transaction)
CREATE TABLE cashier_closing (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  naming_series varchar(140),   -- enum: POS-CLO-
  user_id bigint NOT NULL,   -- -> User
  date date,
  from_time time(6) NOT NULL,
  time time(6) NOT NULL,
  expense numeric(21,9) DEFAULT 0,
  custody numeric(21,9) DEFAULT 0,
  returns numeric(21,2) DEFAULT 0,
  outstanding_amount numeric(21,9) DEFAULT 0,
  net_amount numeric(21,9) DEFAULT 0,
  amended_from_id bigint,   -- -> Cashier Closing
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Cashier Closing.payments line items -> Cashier Closing Payments
CREATE TABLE cashier_closing_payments (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  cashier_closing_id bigint NOT NULL,   -- parent -> Cashier Closing
  line_no integer NOT NULL,   -- was ERPNext `idx`
  mode_of_payment_id bigint NOT NULL,   -- -> Mode of Payment
  amount numeric(21,9) DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Cheque Print Template (master)
CREATE TABLE cheque_print_template (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  has_print_format smallint NOT NULL DEFAULT 0,
  bank_name varchar(140) NOT NULL,
  cheque_size varchar(140),   -- enum: Regular | A4
  starting_position_from_top_edge numeric(21,2) DEFAULT 0,
  cheque_width numeric(21,2) DEFAULT 0,
  cheque_height numeric(21,2) DEFAULT 0,
  scanned_cheque text,
  is_account_payable smallint NOT NULL DEFAULT 1,
  acc_pay_dist_from_top_edge numeric(21,2) DEFAULT 0,
  acc_pay_dist_from_left_edge numeric(21,2) DEFAULT 0,
  message_to_show varchar(140),
  date_dist_from_top_edge numeric(21,2) DEFAULT 0,
  date_dist_from_left_edge numeric(21,2) DEFAULT 0,
  payer_name_from_top_edge numeric(21,2) DEFAULT 0,
  payer_name_from_left_edge numeric(21,2) DEFAULT 0,
  amt_in_words_from_top_edge numeric(21,2) DEFAULT 0,
  amt_in_words_from_left_edge numeric(21,2) DEFAULT 0,
  amt_in_word_width numeric(21,2) DEFAULT 0,
  amt_in_words_line_spacing numeric(21,2) DEFAULT 0,
  amt_in_figures_from_top_edge numeric(21,2) DEFAULT 0,
  amt_in_figures_from_left_edge numeric(21,2) DEFAULT 0,
  acc_no_dist_from_top_edge numeric(21,2) DEFAULT 0,
  acc_no_dist_from_left_edge numeric(21,2) DEFAULT 0,
  signatory_from_top_edge numeric(21,2) DEFAULT 0,
  signatory_from_left_edge numeric(21,2) DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Company (tree-master)
CREATE TABLE company (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  company_name varchar(140) NOT NULL,
  abbr varchar(140) NOT NULL,
  is_group smallint NOT NULL DEFAULT 0,
  default_finance_book_id bigint,   -- -> Finance Book
  domain varchar(140),
  parent_company_id bigint,   -- -> Company
  company_logo text,
  company_description text,
  sales_monthly_history text,
  transactions_annual_history text,
  monthly_sales_target numeric(21,9) DEFAULT 0,
  total_monthly_sales numeric(21,9) DEFAULT 0,
  default_currency_id bigint NOT NULL,   -- -> Currency
  default_letter_head_id bigint,   -- -> Letter Head
  default_holiday_list_id bigint,   -- -> Holiday List
  default_warehouse_for_sales_return_id bigint,   -- -> Warehouse
  country_id bigint NOT NULL,   -- -> Country
  create_chart_of_accounts_based_on varchar(140),   -- enum: Standard Template | Existing Company
  chart_of_accounts varchar(140),
  existing_company_id bigint,   -- -> Company
  tax_id varchar(140),
  date_of_establishment date,
  default_bank_account_id bigint,   -- -> Account
  default_cash_account_id bigint,   -- -> Account
  default_receivable_account_id bigint,   -- -> Account
  round_off_account_id bigint,   -- -> Account
  round_off_cost_center_id bigint,   -- -> Cost Center
  write_off_account_id bigint,   -- -> Account
  exchange_gain_loss_account_id bigint,   -- -> Account
  unrealized_exchange_gain_loss_account_id bigint,   -- -> Account
  allow_account_creation_against_child_company smallint NOT NULL DEFAULT 0,
  default_payable_account_id bigint,   -- -> Account
  default_expense_account_id bigint,   -- -> Account
  default_income_account_id bigint,   -- -> Account
  default_deferred_revenue_account_id bigint,   -- -> Account
  default_deferred_expense_account_id bigint,   -- -> Account
  cost_center_id bigint,   -- -> Cost Center
  credit_limit numeric(21,9) DEFAULT 0,
  payment_terms_id bigint,   -- -> Payment Terms Template
  enable_perpetual_inventory smallint NOT NULL DEFAULT 1,
  default_inventory_account_id bigint,   -- -> Account
  stock_adjustment_account_id bigint,   -- -> Account
  default_purchase_price_variance_account_id bigint,   -- -> Account
  default_manufacturing_variance_account_id bigint,   -- -> Account
  stock_received_but_not_billed_id bigint,   -- -> Account
  accumulated_depreciation_account_id bigint,   -- -> Account
  depreciation_expense_account_id bigint,   -- -> Account
  series_for_depreciation_entry varchar(140),
  disposal_account_id bigint,   -- -> Account
  depreciation_cost_center_id bigint,   -- -> Cost Center
  capital_work_in_progress_account_id bigint,   -- -> Account
  asset_received_but_not_billed_id bigint,   -- -> Account
  exception_budget_approver_role_id bigint,   -- -> Role
  date_of_incorporation date,
  date_of_commencement date,
  phone_no varchar(140),
  fax varchar(140),
  email varchar(140),
  website varchar(140),
  registration_details text,
  lft integer DEFAULT 0,
  rgt integer DEFAULT 0,
  old_parent varchar(140),
  default_selling_terms_id bigint,   -- -> Terms and Conditions
  default_buying_terms_id bigint,   -- -> Terms and Conditions
  default_in_transit_warehouse_id bigint,   -- -> Warehouse
  default_warehouse_id bigint,   -- -> Warehouse
  sample_retention_warehouse_id bigint,   -- -> Warehouse
  unrealized_profit_loss_account_id bigint,   -- -> Account
  default_discount_account_id bigint,   -- -> Account
  enable_provisional_accounting_for_non_stock_items smallint NOT NULL DEFAULT 0,
  default_provisional_account_id bigint,   -- -> Account
  default_advance_received_account_id bigint,   -- -> Account
  default_advance_paid_account_id bigint,   -- -> Account
  book_advance_payments_in_separate_party_account smallint NOT NULL DEFAULT 0,
  auto_exchange_rate_revaluation smallint NOT NULL DEFAULT 0,
  auto_err_frequency varchar(140),   -- enum: Daily | Weekly | Monthly
  submit_err_jv smallint NOT NULL DEFAULT 0,
  reconcile_on_advance_payment_date smallint NOT NULL DEFAULT 0,
  default_operating_cost_account_id bigint,   -- -> Account
  round_off_for_opening_id bigint,   -- -> Account
  reconciliation_takes_effect_on varchar(140),   -- enum: Advance Payment Date | Oldest Of Invoice Or Advance | Reconciliation Date
  reporting_currency_id bigint,   -- -> Currency
  purchase_expense_account_id bigint,   -- -> Account
  purchase_expense_contra_account_id bigint,   -- -> Account
  service_expense_account_id bigint,   -- -> Account
  expenses_added_to_stock_account_id bigint,   -- -> Account
  expenses_added_to_stock_contra_account_id bigint,   -- -> Account
  enable_item_wise_inventory_account smallint NOT NULL DEFAULT 0,
  valuation_method varchar(140) NOT NULL,   -- enum: FIFO | Moving Average | LIFO
  default_wip_warehouse_id bigint,   -- -> Warehouse
  default_fg_warehouse_id bigint,   -- -> Warehouse
  default_scrap_warehouse_id bigint,   -- -> Warehouse
  default_sales_contact_id bigint,   -- -> Contact
  accounts_frozen_till_date date,
  role_allowed_for_frozen_entries_id bigint,   -- -> Role
  default_letter_head_report_id bigint,   -- -> Letter Head
  disable_sdbnb_in_sr smallint NOT NULL DEFAULT 0,
  stock_delivered_but_not_billed_id bigint,   -- -> Account
  enable_stock_delivered_but_not_billed smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Cost Center (tree-master)
CREATE TABLE cost_center (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  cost_center_name varchar(140) NOT NULL,
  cost_center_number varchar(140),
  parent_cost_center_id bigint NOT NULL,   -- -> Cost Center
  company_id bigint NOT NULL,   -- -> Company
  is_group smallint NOT NULL DEFAULT 0,
  lft integer DEFAULT 0,
  rgt integer DEFAULT 0,
  old_parent_id bigint,   -- -> Cost Center
  disabled smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Cost Center Allocation (transaction)
CREATE TABLE cost_center_allocation (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  main_cost_center_id bigint NOT NULL,   -- -> Cost Center
  valid_from date NOT NULL,
  company_id bigint NOT NULL,   -- -> Company
  amended_from_id bigint,   -- -> Cost Center Allocation
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Cost Center Allocation.allocation_percentages line items -> Cost Center Allocation Percentage
CREATE TABLE cost_center_allocation_allocation_percentages (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  cost_center_allocation_id bigint NOT NULL,   -- parent -> Cost Center Allocation
  line_no integer NOT NULL,   -- was ERPNext `idx`
  cost_center_id bigint NOT NULL,   -- -> Cost Center
  percentage numeric(21,9) NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Coupon Code (master)
CREATE TABLE coupon_code (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  coupon_name varchar(140) NOT NULL,
  coupon_type varchar(140) NOT NULL,   -- enum: Promotional | Gift Card
  customer_id bigint,   -- -> Customer
  coupon_code varchar(140),
  pricing_rule_id bigint,   -- -> Pricing Rule
  valid_from date,
  valid_upto date,
  maximum_use integer DEFAULT 0,
  used integer DEFAULT 0,
  description text,
  amended_from_id bigint,   -- -> Coupon Code
  from_external_ecomm_platform smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Currency Exchange (master)
CREATE TABLE currency_exchange (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  date date NOT NULL,
  from_currency_id bigint NOT NULL,   -- -> Currency
  to_currency_id bigint NOT NULL,   -- -> Currency
  exchange_rate numeric(21,9) NOT NULL DEFAULT 0,
  for_buying smallint NOT NULL DEFAULT 1,
  for_selling smallint NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Customer (master)
CREATE TABLE customer (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  naming_series varchar(140),   -- enum: CUST-.YYYY.-
  customer_name varchar(140) NOT NULL,
  gender_id bigint,   -- -> Gender
  customer_type varchar(140) NOT NULL,   -- enum: Company | Individual | Partnership
  default_bank_account_id bigint,   -- -> Bank Account
  lead_name_id bigint,   -- -> Lead
  image text,
  account_manager_id bigint,   -- -> User
  customer_group_id bigint,   -- -> Customer Group
  territory_id bigint,   -- -> Territory
  tax_id varchar(140),
  tax_category_id bigint,   -- -> Tax Category
  disabled smallint NOT NULL DEFAULT 0,
  is_internal_customer smallint NOT NULL DEFAULT 0,
  represents_company_id bigint,   -- -> Company
  default_currency_id bigint,   -- -> Currency
  default_price_list_id bigint,   -- -> Price List
  language_id bigint,   -- -> Language
  website varchar(140),
  customer_primary_contact_id bigint,   -- -> Contact
  mobile_no varchar(140),   -- denormalised from customer_primary_contact.mobile_no
  email_id varchar(140),   -- denormalised from customer_primary_contact.email_id
  customer_primary_address_id bigint,   -- -> Address
  primary_address text,
  payment_terms_id bigint,   -- -> Payment Terms Template
  customer_details text,
  market_segment_id bigint,   -- -> Market Segment
  industry_id bigint,   -- -> Industry Type
  is_frozen smallint NOT NULL DEFAULT 0,
  loyalty_program_id bigint,   -- -> Loyalty Program
  loyalty_program_tier varchar(140),
  default_sales_partner_id bigint,   -- -> Sales Partner
  default_commission_rate numeric(21,9) DEFAULT 0,
  customer_pos_id varchar(140),
  so_required smallint NOT NULL DEFAULT 0,
  dn_required smallint NOT NULL DEFAULT 0,
  tax_withholding_category_id bigint,   -- -> Tax Withholding Category
  opportunity_name_id bigint,   -- -> Opportunity
  restrict_to_companies smallint NOT NULL DEFAULT 0,
  prospect_name_id bigint,   -- -> Prospect
  first_name varchar(140),   -- denormalised from customer_primary_contact.first_name
  last_name varchar(140),   -- denormalised from customer_primary_contact.last_name
  tax_withholding_group_id bigint,   -- -> Tax Withholding Group
  alias varchar(140),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Customer.accounts line items -> Party Account
CREATE TABLE customer_accounts (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id bigint NOT NULL,   -- parent -> Customer
  line_no integer NOT NULL,   -- was ERPNext `idx`
  company_id bigint NOT NULL,   -- -> Company
  account_id bigint,   -- -> Account
  advance_account_id bigint,   -- -> Account
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Customer.allowed_companies line items -> Company Restriction
CREATE TABLE customer_allowed_companies (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id bigint NOT NULL,   -- parent -> Customer
  line_no integer NOT NULL,   -- was ERPNext `idx`
  company_id bigint NOT NULL,   -- -> Company
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Customer.companies line items -> Allowed To Transact With
CREATE TABLE customer_companies (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id bigint NOT NULL,   -- parent -> Customer
  line_no integer NOT NULL,   -- was ERPNext `idx`
  company_id bigint NOT NULL,   -- -> Company
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Customer.credit_limits line items -> Customer Credit Limit
CREATE TABLE customer_credit_limits (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id bigint NOT NULL,   -- parent -> Customer
  line_no integer NOT NULL,   -- was ERPNext `idx`
  credit_limit numeric(21,9) DEFAULT 0,
  overdue_billing_threshold numeric(21,9) DEFAULT 0,
  company_id bigint,   -- -> Company
  bypass_credit_limit_check smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Customer Group (tree-master)
CREATE TABLE customer_group (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  customer_group_name varchar(140) NOT NULL,
