  line_no integer NOT NULL,   -- was ERPNext `idx`
  company_id bigint NOT NULL,   -- -> Company
  account_id bigint,   -- -> Account
  advance_account_id bigint,   -- -> Account
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Customer Group.credit_limits line items -> Customer Credit Limit
CREATE TABLE customer_group_credit_limits (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_group_id bigint NOT NULL,   -- parent -> Customer Group
  line_no integer NOT NULL,   -- was ERPNext `idx`
  credit_limit numeric(21,9) DEFAULT 0,
  overdue_billing_threshold numeric(21,9) DEFAULT 0,
  company_id bigint,   -- -> Company
  bypass_credit_limit_check smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Customer.portal_users line items -> Portal User
CREATE TABLE customer_portal_users (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id bigint NOT NULL,   -- parent -> Customer
  line_no integer NOT NULL,   -- was ERPNext `idx`
  user_id bigint NOT NULL,   -- -> User
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Customer.sales_team line items -> Sales Team
CREATE TABLE customer_sales_team (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id bigint NOT NULL,   -- parent -> Customer
  line_no integer NOT NULL,   -- was ERPNext `idx`
  sales_person_id bigint NOT NULL,   -- -> Sales Person
  contact_no varchar(140),
  allocated_percentage numeric(21,9) DEFAULT 0,
  allocated_amount numeric(21,9) DEFAULT 0,
  commission_rate numeric(21,9) DEFAULT 0,   -- denormalised from sales_person.commission_rate
  incentives numeric(21,9) DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Customer.supplier_numbers line items -> Supplier Number At Customer
CREATE TABLE customer_supplier_numbers (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id bigint NOT NULL,   -- parent -> Customer
  line_no integer NOT NULL,   -- was ERPNext `idx`
  company_id bigint,   -- -> Company
  supplier_number varchar(140),
