-- Delivery Note (transaction)
CREATE TABLE delivery_note (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  naming_series varchar(140) NOT NULL,   -- enum: MAT-DN-.YYYY.- | MAT-DN-RET-.YYYY.-
  customer_id bigint NOT NULL,   -- -> Customer
  customer_name varchar(140),   -- denormalised from customer.customer_name
  amended_from_id bigint,   -- -> Delivery Note
  company_id bigint NOT NULL,   -- -> Company
  posting_date date NOT NULL,
  posting_time time(6) NOT NULL,
  set_posting_time smallint NOT NULL DEFAULT 0,
  is_return smallint NOT NULL DEFAULT 0,
  issue_credit_note smallint NOT NULL DEFAULT 0,
  return_against_id bigint,   -- -> Delivery Note
  po_no text,
  po_date date,
  shipping_address_name_id bigint,   -- -> Address
  shipping_address text,
  contact_person_id bigint,   -- -> Contact
  contact_display text,
  contact_mobile text,
  contact_email varchar(140),
  customer_address_id bigint,   -- -> Address
  tax_id varchar(140),
  address_display text,
  company_address_id bigint,   -- -> Address
  company_address_display text,
  currency_id bigint NOT NULL,   -- -> Currency
  conversion_rate numeric(21,9) NOT NULL DEFAULT 0,
  selling_price_list_id bigint NOT NULL,   -- -> Price List
  price_list_currency_id bigint NOT NULL,   -- -> Currency
  plc_conversion_rate numeric(21,9) NOT NULL DEFAULT 0,
  ignore_pricing_rule smallint NOT NULL DEFAULT 0,
  set_warehouse_id bigint,   -- -> Warehouse
  scan_barcode varchar(140),
  total_qty numeric(21,9) DEFAULT 0,
  base_total numeric(21,9) DEFAULT 0,
  base_net_total numeric(21,9) DEFAULT 0,
  total numeric(21,9) DEFAULT 0,
  net_total numeric(21,9) DEFAULT 0,
  total_net_weight numeric(21,9) DEFAULT 0,
  tax_category_id bigint,   -- -> Tax Category
  shipping_rule_id bigint,   -- -> Shipping Rule
  taxes_and_charges_id bigint,   -- -> Sales Taxes and Charges Template
  other_charges_calculation text,
  base_total_taxes_and_charges numeric(21,9) DEFAULT 0,
  total_taxes_and_charges numeric(21,9) DEFAULT 0,
  apply_discount_on varchar(140),   -- enum: Grand Total | Net Total
  base_discount_amount numeric(21,9) DEFAULT 0,
  additional_discount_percentage numeric(21,9) DEFAULT 0,
  discount_amount numeric(21,9) DEFAULT 0,
  base_grand_total numeric(21,9) DEFAULT 0,
  base_rounding_adjustment numeric(21,9) DEFAULT 0,
  base_rounded_total numeric(21,9) DEFAULT 0,
  base_in_words varchar(140),
  grand_total numeric(21,9) DEFAULT 0,
  rounding_adjustment numeric(21,9) DEFAULT 0,
  rounded_total numeric(21,9) DEFAULT 0,
  in_words varchar(140),
  tc_name_id bigint,   -- -> Terms and Conditions
  terms text,
  transporter_id bigint,   -- -> Supplier
  driver_id bigint,   -- -> Driver
  lr_no varchar(140),
  vehicle_no varchar(140),
  transporter_name varchar(140),   -- denormalised from transporter.supplier_name
  driver_name varchar(140),   -- denormalised from driver.full_name
  lr_date date,
  project_id bigint,   -- -> Project
  per_billed numeric(21,9) DEFAULT 0,
  customer_group_id bigint,   -- -> Customer Group
  territory_id bigint,   -- -> Territory
  letter_head_id bigint,   -- -> Letter Head
  select_print_heading_id bigint,   -- -> Print Heading
  language_id bigint,   -- -> Language
  print_without_amount smallint NOT NULL DEFAULT 0,
  group_same_items smallint NOT NULL DEFAULT 0,
  status varchar(140) NOT NULL,   -- enum: Draft | To Bill | Partially Billed | Completed | Return | Return Issued
  per_installed numeric(21,9) DEFAULT 0,
  installation_status varchar(140),
  excise_page varchar(140),
  instructions text,
  auto_repeat_id bigint,   -- -> Auto Repeat
  sales_partner_id bigint,   -- -> Sales Partner
  commission_rate numeric(21,9) DEFAULT 0,   -- denormalised from sales_partner.commission_rate
  total_commission numeric(21,9) DEFAULT 0,
  is_internal_customer smallint NOT NULL DEFAULT 0,   -- denormalised from customer.is_internal_customer
  inter_company_reference_id bigint,   -- -> Purchase Receipt
  per_returned numeric(21,9) DEFAULT 0,
  set_target_warehouse_id bigint,   -- -> Warehouse
  represents_company_id bigint,   -- -> Company
  disable_rounded_total smallint NOT NULL DEFAULT 0,
  dispatch_address_name_id bigint,   -- -> Address
  dispatch_address text,
  amount_eligible_for_commission numeric(21,9) DEFAULT 0,
  cost_center_id bigint,   -- -> Cost Center
  incoterm_id bigint,   -- -> Incoterm
  named_place varchar(140),
  delivery_trip_id bigint,   -- -> Delivery Trip
  utm_medium_id bigint,   -- -> UTM Medium
  utm_content varchar(140),
  utm_source_id bigint,   -- -> UTM Source
  utm_campaign_id bigint,   -- -> UTM Campaign
  company_contact_person_id bigint,   -- -> Contact
  title varchar(140),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

