  allow_zero_valuation_rate smallint NOT NULL DEFAULT 0,
  against_sales_order_id bigint,   -- -> Sales Order
  against_sales_invoice_id bigint,   -- -> Sales Invoice
  so_detail varchar(140),
  si_detail varchar(140),
  installed_qty numeric(21,9) DEFAULT 0,
  billed_amt numeric(21,9) DEFAULT 0,
  page_break smallint NOT NULL DEFAULT 0,
  project_id bigint,   -- -> Project
  dn_detail varchar(140),
  returned_qty numeric(21,9) DEFAULT 0,
  incoming_rate numeric(21,9) DEFAULT 0,
  stock_uom_rate numeric(21,9) DEFAULT 0,
  grant_commission smallint NOT NULL DEFAULT 0,   -- denormalised from item_code.grant_commission
  pick_list_item varchar(140),
  purchase_order_id bigint,   -- -> Purchase Order
  purchase_order_item varchar(140),
  has_item_scanned smallint NOT NULL DEFAULT 0,
  material_request_id bigint,   -- -> Material Request
  material_request_item varchar(140),
  received_qty numeric(21,9) DEFAULT 0,
  packed_qty numeric(21,9) DEFAULT 0,
  serial_and_batch_bundle_id bigint,   -- -> Serial and Batch Bundle
  serial_no text,
  batch_no_id bigint,   -- -> Batch
  use_serial_batch_fields smallint NOT NULL DEFAULT 0,
  distributed_discount_amount numeric(21,9) DEFAULT 0,
  company_total_stock numeric(21,9) DEFAULT 0,
  against_pick_list_id bigint,   -- -> Pick List
