  create_user_automatically smallint NOT NULL DEFAULT 0,
  scheduled_confirmation_date date,
  final_confirmation_date date,
  contract_end_date date,
  notice_number_of_days integer DEFAULT 0,
  date_of_retirement date,
  department_id bigint,   -- -> Department
  designation_id bigint,   -- -> Designation
  reports_to_id bigint,   -- -> Employee
  branch_id bigint,   -- -> Branch
  holiday_list_id bigint,   -- -> Holiday List
  salary_mode varchar(140),   -- enum: Bank | Cash | Cheque
  bank_name varchar(140),
  bank_ac_no varchar(140),
  cell_number varchar(140),
  prefered_contact_email varchar(140),   -- enum: Company Email | Personal Email | User ID
  prefered_email varchar(140),
  company_email varchar(140),
  personal_email varchar(140),
  unsubscribed smallint NOT NULL DEFAULT 0,
  permanent_accommodation_type varchar(140),   -- enum: Rented | Owned
  permanent_address text,
  current_accommodation_type varchar(140),   -- enum: Rented | Owned
  current_address text,
  bio text,
  passport_number varchar(140),
  date_of_issue date,
  valid_upto date,
  place_of_issue varchar(140),
  marital_status varchar(140),   -- enum: Single | Married | Divorced | Widowed
  blood_group varchar(140),   -- enum: A+ | A- | B+ | B- | AB+ | AB-
  family_background text,
  health_details text,
  resignation_letter_date date,
  relieving_date date,
  reason_for_leaving text,
  leave_encashed varchar(140),   -- enum: Yes | No
  encashment_date date,
  held_on date,
  new_workplace varchar(140),
  feedback text,
  lft integer DEFAULT 0,
  rgt integer DEFAULT 0,
  old_parent varchar(140),
  attendance_device_id varchar(140),
  salary_currency_id bigint,   -- -> Currency
  ctc numeric(21,9) DEFAULT 0,
  iban varchar(140),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

