-- Journal Entry (transaction)
CREATE TABLE journal_entry (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  title varchar(140),
  voucher_type varchar(140) NOT NULL,   -- enum: Journal Entry | Inter Company Journal Entry | Bank Entry | Cash Entry | Credit Card Entry | Debit Note
  naming_series varchar(140) NOT NULL,   -- enum: ACC-JV-.YYYY.-
  posting_date date NOT NULL,
  company_id bigint NOT NULL,   -- -> Company
  finance_book_id bigint,   -- -> Finance Book
  cheque_no varchar(140),
  cheque_date date,
  user_remark text,
  total_debit numeric(21,9) DEFAULT 0,
  total_credit numeric(21,9) DEFAULT 0,
  difference numeric(21,9) DEFAULT 0,
  multi_currency smallint NOT NULL DEFAULT 0,
  total_amount_currency_id bigint,   -- -> Currency
  total_amount numeric(21,9) DEFAULT 0,
  total_amount_in_words varchar(140),
  clearance_date date,
  remark text,
  inter_company_journal_entry_reference_id bigint,   -- -> Journal Entry
  bill_no varchar(140),
  bill_date date,
  due_date date,
  write_off_based_on varchar(140),   -- enum: Accounts Receivable | Accounts Payable
  write_off_amount numeric(21,9) DEFAULT 0,
  pay_to_recd_from varchar(140),
  letter_head_id bigint,   -- -> Letter Head
  select_print_heading_id bigint,   -- -> Print Heading
  mode_of_payment_id bigint,   -- -> Mode of Payment
  payment_order_id bigint,   -- -> Payment Order
  is_opening varchar(140),   -- enum: No | Yes
  stock_entry_id bigint,   -- -> Stock Entry
  auto_repeat_id bigint,   -- -> Auto Repeat
  amended_from_id bigint,   -- -> Journal Entry
  from_template_id bigint,   -- -> Journal Entry Template
  tax_withholding_category_id bigint,   -- -> Tax Withholding Category
  apply_tds smallint NOT NULL DEFAULT 0,
  reversal_of_id bigint,   -- -> Journal Entry
  process_deferred_accounting_id bigint,   -- -> Process Deferred Accounting
  is_system_generated smallint NOT NULL DEFAULT 0,
  periodic_entry_difference_account_id bigint,   -- -> Account
  for_all_stock_asset_accounts smallint NOT NULL DEFAULT 1,
  stock_asset_account_id bigint,   -- -> Account
  party_not_required smallint NOT NULL DEFAULT 0,
  tax_withholding_group_id bigint,   -- -> Tax Withholding Group
  ignore_tax_withholding_threshold smallint NOT NULL DEFAULT 0,
  override_tax_withholding_entries smallint NOT NULL DEFAULT 0,
  custom_remark smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Journal Entry.accounts line items -> Journal Entry Account
CREATE TABLE journal_entry_accounts (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  journal_entry_id bigint NOT NULL,   -- parent -> Journal Entry
  line_no integer NOT NULL,   -- was ERPNext `idx`
  account_id bigint NOT NULL,   -- -> Account
  account_type varchar(140),
  cost_center_id bigint,   -- -> Cost Center
  party_type_id bigint,   -- -> DocType
  party varchar(140),   -- polymorphic: target doctype in party_type
  account_currency_id bigint,   -- -> Currency
  exchange_rate numeric(21,9) DEFAULT 0,
  debit_in_account_currency numeric(21,9) DEFAULT 0,
  debit numeric(21,9) DEFAULT 0,
  credit_in_account_currency numeric(21,9) DEFAULT 0,
  credit numeric(21,9) DEFAULT 0,
  reference_type varchar(140),   -- enum: Sales Invoice | Purchase Invoice | Journal Entry | Sales Order | Purchase Order | Expense Claim
  reference_name varchar(140),   -- polymorphic: target doctype in reference_type
  reference_due_date date,
  project_id bigint,   -- -> Project
  is_advance varchar(140),   -- enum: No | Yes
  user_remark text,
  against_account text,
  bank_account_id bigint,   -- -> Bank Account
  reference_detail_no varchar(140),
  advance_voucher_type_id bigint,   -- -> DocType
  advance_voucher_no varchar(140),   -- polymorphic: target doctype in advance_voucher_type
  is_tax_withholding_account smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Journal Entry.tax_withholding_entries line items -> Tax Withholding Entry
CREATE TABLE journal_entry_tax_withholding_entries (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  journal_entry_id bigint NOT NULL,   -- parent -> Journal Entry
  line_no integer NOT NULL,   -- was ERPNext `idx`
  party_type_id bigint,   -- -> DocType
  party varchar(140),   -- polymorphic: target doctype in party_type
  tax_id varchar(140),
  tax_withholding_category_id bigint,   -- -> Tax Withholding Category
  tax_rate numeric(21,9) DEFAULT 0,
  taxable_amount numeric(21,9) DEFAULT 0,
  lower_deduction_certificate_id bigint,   -- -> Lower Deduction Certificate
  status varchar(140),   -- enum: Settled | Under Withheld | Over Withheld | Duplicate | Cancelled
  currency_id bigint,   -- -> Currency
  conversion_rate numeric(21,9) DEFAULT 0,
  withholding_doctype_id bigint,   -- -> DocType
  withholding_name varchar(140),   -- polymorphic: target doctype in withholding_doctype
  taxable_doctype_id bigint,   -- -> DocType
  taxable_name varchar(140),   -- polymorphic: target doctype in taxable_doctype
  taxable_date date,
  withholding_date date,
  under_withheld_reason varchar(140),   -- enum: Threshold Exemption | Lower Deduction Certificate
  withholding_amount numeric(21,9) DEFAULT 0,
  tax_withholding_group_id bigint,   -- -> Tax Withholding Group
  company_id bigint,   -- -> Company
  created_by_migration smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

