-- Material Request (transaction)
CREATE TABLE material_request (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  naming_series varchar(140) NOT NULL,   -- enum: MAT-MR-.YYYY.-
  title varchar(140),
  material_request_type varchar(140) NOT NULL,   -- enum: Purchase | Material Transfer | Material Issue | Manufacture | Subcontracting | Customer Provided
  customer_id bigint,   -- -> Customer
  schedule_date date,
  company_id bigint NOT NULL,   -- -> Company
  amended_from_id bigint,   -- -> Material Request
  scan_barcode varchar(140),
  transaction_date date NOT NULL,
  status varchar(140),   -- enum: Draft | Submitted | Stopped | Cancelled | Pending | Partially Ordered
  per_ordered numeric(21,9) DEFAULT 0,
  per_received numeric(21,9) DEFAULT 0,
  letter_head_id bigint,   -- -> Letter Head
  select_print_heading_id bigint,   -- -> Print Heading
  tc_name_id bigint,   -- -> Terms and Conditions
  terms text,
  job_card_id bigint,   -- -> Job Card
  set_warehouse_id bigint,   -- -> Warehouse
  set_from_warehouse_id bigint,   -- -> Warehouse
  transfer_status varchar(140),   -- enum: Not Started | In Transit | Completed
  work_order_id bigint,   -- -> Work Order
  buying_price_list_id bigint,   -- -> Price List
  auto_created_via_reorder smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Material Request.items line items -> Material Request Item
CREATE TABLE material_request_items (
