  material_request_plan_item varchar(140),
  min_order_qty numeric(21,9) DEFAULT 0,
  projected_qty numeric(21,9) DEFAULT 0,
  actual_qty numeric(21,9) DEFAULT 0,
  ordered_qty numeric(21,9) DEFAULT 0,
  expense_account_id bigint,   -- -> Account
  cost_center_id bigint,   -- -> Cost Center
  page_break smallint NOT NULL DEFAULT 0,
  received_qty numeric(21,9) DEFAULT 0,
  manufacturer_id bigint,   -- -> Manufacturer
  manufacturer_part_no varchar(140),
  from_warehouse_id bigint,   -- -> Warehouse
  bom_no_id bigint,   -- -> BOM
  job_card_item varchar(140),
  wip_composite_asset_id bigint,   -- -> Asset
  price_list_rate numeric(21,9) DEFAULT 0,
  reorder_level numeric(21,9) DEFAULT 0,
  reorder_qty numeric(21,9) DEFAULT 0,
  projected_on_hand numeric(21,9) DEFAULT 0,
  picked_qty numeric(21,9) DEFAULT 0,
  packed_item varchar(140),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

