  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Payment Entry (transaction)
CREATE TABLE payment_entry (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  naming_series varchar(140) NOT NULL,   -- enum: ACC-PAY-.YYYY.-
  payment_type varchar(140) NOT NULL,   -- enum: Receive | Pay | Internal Transfer
  posting_date date NOT NULL,
  company_id bigint NOT NULL,   -- -> Company
  cost_center_id bigint,   -- -> Cost Center
  mode_of_payment_id bigint,   -- -> Mode of Payment
  party_type_id bigint,   -- -> DocType
  party varchar(140),   -- polymorphic: target doctype in party_type
  party_name varchar(140),
  contact_person_id bigint,   -- -> Contact
  contact_email varchar(140),
  paid_from_id bigint NOT NULL,   -- -> Account
  paid_from_account_currency_id bigint NOT NULL,   -- -> Currency
  paid_to_id bigint NOT NULL,   -- -> Account
  paid_to_account_currency_id bigint NOT NULL,   -- -> Currency
  paid_amount numeric(21,9) NOT NULL DEFAULT 0,
  source_exchange_rate numeric(21,9) NOT NULL DEFAULT 0,
  base_paid_amount numeric(21,9) NOT NULL DEFAULT 0,
  received_amount numeric(21,9) NOT NULL DEFAULT 0,
  target_exchange_rate numeric(21,9) NOT NULL DEFAULT 0,
  base_received_amount numeric(21,9) NOT NULL DEFAULT 0,
  total_allocated_amount numeric(21,9) DEFAULT 0,
  base_total_allocated_amount numeric(21,9) DEFAULT 0,
  unallocated_amount numeric(21,9) DEFAULT 0,
  difference_amount numeric(21,9) DEFAULT 0,
  reference_no varchar(140),
  reference_date date,
  clearance_date date,
  project_id bigint,   -- -> Project
  remarks text,
  letter_head_id bigint,   -- -> Letter Head
  print_heading_id bigint,   -- -> Print Heading
  bank varchar(140),   -- denormalised from bank_account.bank
  bank_account_no varchar(140),   -- denormalised from bank_account.bank_account_no
  payment_order_id bigint,   -- -> Payment Order
  auto_repeat_id bigint,   -- -> Auto Repeat
  amended_from_id bigint,   -- -> Payment Entry
  title varchar(140),
  bank_account_id bigint,   -- -> Bank Account
  party_bank_account_id bigint,   -- -> Bank Account
  payment_order_status varchar(140),   -- enum: Initiated | Payment Ordered
  status varchar(140),   -- enum: Draft | Submitted | Cancelled
  custom_remarks smallint NOT NULL DEFAULT 0,
  tax_withholding_category_id bigint,   -- -> Tax Withholding Category
  purchase_taxes_and_charges_template_id bigint,   -- -> Purchase Taxes and Charges Template
  sales_taxes_and_charges_template_id bigint,   -- -> Sales Taxes and Charges Template
  base_total_taxes_and_charges numeric(21,9) DEFAULT 0,
  total_taxes_and_charges numeric(21,9) DEFAULT 0,
  paid_amount_after_tax numeric(21,9) DEFAULT 0,
  base_paid_amount_after_tax numeric(21,9) DEFAULT 0,
  received_amount_after_tax numeric(21,9) DEFAULT 0,
  base_received_amount_after_tax numeric(21,9) DEFAULT 0,
  paid_from_account_type varchar(140),   -- denormalised from paid_from.account_type
  paid_to_account_type varchar(140),   -- denormalised from paid_to.account_type
  book_advance_payments_in_separate_party_account smallint NOT NULL DEFAULT 0,   -- denormalised from company.book_advance_payments_in_separate_party_account
  base_in_words text,
  in_words text,
  reconcile_on_advance_payment_date smallint NOT NULL DEFAULT 0,   -- denormalised from company.reconcile_on_advance_payment_date
  is_opening varchar(140),   -- enum: No | Yes
  apply_tds smallint NOT NULL DEFAULT 0,
  tax_withholding_group_id bigint,   -- -> Tax Withholding Group
  ignore_tax_withholding_threshold smallint NOT NULL DEFAULT 0,
  override_tax_withholding_entries smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Payment Entry.deductions line items -> Payment Entry Deduction
CREATE TABLE payment_entry_deductions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
