  amount numeric(21,9) NOT NULL DEFAULT 0,
  description text,
  is_exchange_gain_loss smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Payment Entry.references line items -> Payment Entry Reference
CREATE TABLE payment_entry_references (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  payment_entry_id bigint NOT NULL,   -- parent -> Payment Entry
  line_no integer NOT NULL,   -- was ERPNext `idx`
  reference_doctype_id bigint NOT NULL,   -- -> DocType
  reference_name varchar(140) NOT NULL,   -- polymorphic: target doctype in reference_doctype
