  bill_no varchar(140),
  total_amount numeric(21,9) DEFAULT 0,
  outstanding_amount numeric(21,9) DEFAULT 0,
  allocated_amount numeric(21,9) DEFAULT 0,
  exchange_rate numeric(21,9) DEFAULT 0,
  payment_term_id bigint,   -- -> Payment Term
  exchange_gain_loss numeric(21,9) DEFAULT 0,
  account_id bigint,   -- -> Account
