-- Payment Request (transaction)
CREATE TABLE payment_request (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  payment_request_type varchar(140) NOT NULL,   -- enum: Outward | Inward
  transaction_date date,
  naming_series varchar(140) NOT NULL,   -- enum: ACC-PRQ-.YYYY.-
  mode_of_payment_id bigint,   -- -> Mode of Payment
  party_type_id bigint,   -- -> DocType
  party varchar(140),   -- polymorphic: target doctype in party_type
  reference_doctype_id bigint,   -- -> DocType
  reference_name varchar(140),   -- polymorphic: target doctype in reference_doctype
  grand_total numeric(21,9) NOT NULL DEFAULT 0,
  is_a_subscription smallint NOT NULL DEFAULT 0,
  currency_id bigint,   -- -> Currency
  bank_account_id bigint,   -- -> Bank Account
  bank_id bigint,   -- -> Bank
  bank_account_no varchar(140),   -- denormalised from bank_account.bank_account_no
  account varchar(140),   -- denormalised from bank_account.account
  iban varchar(140),   -- denormalised from bank_account.iban
  branch_code varchar(140),   -- denormalised from bank_account.branch_code
  swift_number varchar(140),   -- denormalised from bank.swift_number
  cost_center_id bigint,   -- -> Cost Center
  project_id bigint,   -- -> Project
  print_format varchar(140),
  email_to varchar(140),
  subject varchar(140),
  payment_gateway_account_id bigint,   -- -> Payment Gateway Account
  status varchar(140),   -- enum: Draft | Requested | Initiated | Partially Paid | Payment Ordered | Paid
  make_sales_invoice smallint NOT NULL DEFAULT 0,
  message text,
  mute_email smallint NOT NULL DEFAULT 0,
  payment_url varchar(140),
  payment_gateway varchar(140),   -- denormalised from payment_gateway_account.payment_gateway
  payment_account varchar(140),   -- denormalised from payment_gateway_account.payment_account
  payment_channel varchar(140),   -- enum: Email | Phone | Other
  payment_order_id bigint,   -- -> Payment Order
  amended_from_id bigint,   -- -> Payment Request
  failed_reason varchar(140),
  outstanding_amount numeric(21,9) DEFAULT 0,
  company_id bigint,   -- -> Company
  party_account_currency_id bigint,   -- -> Currency
  party_name varchar(140),
  phone_number varchar(140),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

