  country varchar(140),   -- denormalised from company.country
  company_address_id bigint,   -- -> Address
  letter_head_id bigint,   -- -> Letter Head
  tc_name_id bigint,   -- -> Terms and Conditions
  select_print_heading_id bigint,   -- -> Print Heading
  selling_price_list_id bigint,   -- -> Price List
  currency_id bigint NOT NULL,   -- -> Currency
  write_off_account_id bigint NOT NULL,   -- -> Account
  write_off_cost_center_id bigint NOT NULL,   -- -> Cost Center
  account_for_change_amount_id bigint,   -- -> Account
  income_account_id bigint,   -- -> Account
  expense_account_id bigint,   -- -> Account
  cost_center_id bigint,   -- -> Cost Center
  taxes_and_charges_id bigint,   -- -> Sales Taxes and Charges Template
  apply_discount_on varchar(140),   -- enum: Grand Total | Net Total
  tax_category_id bigint,   -- -> Tax Category
  print_format_id bigint,   -- -> Print Format
  warehouse_id bigint NOT NULL,   -- -> Warehouse
  ignore_pricing_rule smallint NOT NULL DEFAULT 0,
  update_stock smallint NOT NULL DEFAULT 1,
  hide_unavailable_items smallint NOT NULL DEFAULT 0,
  hide_images smallint NOT NULL DEFAULT 0,
  auto_add_item_to_cart smallint NOT NULL DEFAULT 0,
  allow_rate_change smallint NOT NULL DEFAULT 0,
  allow_discount_change smallint NOT NULL DEFAULT 0,
  validate_stock_on_save smallint NOT NULL DEFAULT 0,
  write_off_limit numeric(21,9) NOT NULL DEFAULT 0,
  disable_rounded_total smallint NOT NULL DEFAULT 0,
  utm_campaign_id bigint,   -- -> UTM Campaign
  utm_source_id bigint,   -- -> UTM Source
  utm_medium_id bigint,   -- -> UTM Campaign
  print_receipt_on_order_complete smallint NOT NULL DEFAULT 0,
  project_id bigint,   -- -> Project
  set_grand_total_to_default_mop smallint NOT NULL DEFAULT 1,
  action_on_new_invoice varchar(140),   -- enum: Always Ask | Save Changes and Load New Invoice | Discard Changes and Load New Invoice
  allow_partial_payment smallint NOT NULL DEFAULT 0,
  allow_warehouse_change smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

