-- Pricing Rule (master)
CREATE TABLE pricing_rule (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  title varchar(140) NOT NULL,
  disable smallint NOT NULL DEFAULT 0,
  apply_on varchar(140) NOT NULL,   -- enum: Item Code | Item Group | Brand | Transaction
  price_or_product_discount varchar(140) NOT NULL,   -- enum: Price | Product
  warehouse_id bigint,   -- -> Warehouse
  mixed_conditions smallint NOT NULL DEFAULT 0,
  is_cumulative smallint NOT NULL DEFAULT 0,
  coupon_code_based smallint NOT NULL DEFAULT 0,
  apply_rule_on_other varchar(140),   -- enum: Item Code | Item Group | Brand
  other_item_code_id bigint,   -- -> Item
  other_item_group_id bigint,   -- -> Item Group
  other_brand_id bigint,   -- -> Brand
  selling smallint NOT NULL DEFAULT 0,
  buying smallint NOT NULL DEFAULT 0,
  applicable_for varchar(140),   -- enum: Customer | Customer Group | Territory | Sales Partner | Campaign | Supplier
  customer_id bigint,   -- -> Customer
  customer_group_id bigint,   -- -> Customer Group
  territory_id bigint,   -- -> Territory
  sales_partner_id bigint,   -- -> Sales Partner
  campaign_id bigint,   -- -> UTM Campaign
  supplier_id bigint,   -- -> Supplier
  supplier_group_id bigint,   -- -> Supplier Group
  min_qty numeric(21,9) DEFAULT 0,
  max_qty numeric(21,9) DEFAULT 0,
  min_amt numeric(21,9) DEFAULT 0,
  max_amt numeric(21,9) DEFAULT 0,
  valid_from date,
  valid_upto date,
  company_id bigint,   -- -> Company
  currency_id bigint NOT NULL,   -- -> Currency
  margin_type varchar(140),   -- enum: Percentage | Amount
  margin_rate_or_amount numeric(21,9) DEFAULT 0,
  rate_or_discount varchar(140),   -- enum: Rate | Discount Percentage | Discount Amount
  apply_discount_on varchar(140),   -- enum: Grand Total | Net Total
  rate numeric(21,9) DEFAULT 0,
  discount_amount numeric(21,9) DEFAULT 0,
  discount_percentage numeric(21,9) DEFAULT 0,
  for_price_list_id bigint,   -- -> Price List
  same_item smallint NOT NULL DEFAULT 0,
  free_item_id bigint,   -- -> Item
  free_qty numeric(21,9) DEFAULT 0,
  free_item_uom_id bigint,   -- -> UOM
  free_item_rate numeric(21,9) DEFAULT 0,
  threshold_percentage numeric(21,9) DEFAULT 0,
  priority varchar(140),   -- enum: 1 | 2 | 3 | 4 | 5 | 6
  apply_multiple_pricing_rules smallint NOT NULL DEFAULT 0,
  apply_discount_on_rate smallint NOT NULL DEFAULT 0,
  validate_applied_rule smallint NOT NULL DEFAULT 0,
  rule_description text,
  promotional_scheme_id varchar(140),
  promotional_scheme_fk bigint,   -- -> Promotional Scheme
  condition text,
  is_recursive smallint NOT NULL DEFAULT 0,
  naming_series varchar(140),   -- enum: PRLE-.####
  round_free_qty smallint NOT NULL DEFAULT 0,
  recurse_for numeric(21,9) DEFAULT 0,
  apply_recursion_over numeric(21,9) DEFAULT 0,
  has_priority smallint NOT NULL DEFAULT 0,
  dont_enforce_free_item_qty smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Pricing Rule.brands line items -> Pricing Rule Brand
CREATE TABLE pricing_rule_brands (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
