CREATE TABLE quality_inspection (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  naming_series varchar(140) NOT NULL,   -- enum: MAT-QA-.YYYY.-
  report_date date NOT NULL,
  inspection_type varchar(140) NOT NULL,   -- enum: Incoming | Outgoing | In Process
  reference_type varchar(140) NOT NULL,   -- enum: Purchase Receipt | Purchase Invoice | Subcontracting Receipt | Delivery Note | Sales Invoice | Stock Entry
  reference_name varchar(140) NOT NULL,   -- polymorphic: target doctype in reference_type
  item_code_id bigint NOT NULL,   -- -> Item
  item_serial_no_id bigint,   -- -> Serial No
