  ignore_pricing_rule smallint NOT NULL DEFAULT 0,
  set_warehouse_id bigint,   -- -> Warehouse
  update_stock smallint NOT NULL DEFAULT 0,
  scan_barcode varchar(140),
  total_billing_amount numeric(21,9) DEFAULT 0,
  total_qty numeric(21,9) DEFAULT 0,
  base_total numeric(21,9) DEFAULT 0,
  base_net_total numeric(21,9) NOT NULL DEFAULT 0,
  total numeric(21,9) DEFAULT 0,
  net_total numeric(21,9) DEFAULT 0,
  total_net_weight numeric(21,9) DEFAULT 0,
  taxes_and_charges_id bigint,   -- -> Sales Taxes and Charges Template
  shipping_rule_id bigint,   -- -> Shipping Rule
  tax_category_id bigint,   -- -> Tax Category
  other_charges_calculation text,
  base_total_taxes_and_charges numeric(21,9) DEFAULT 0,
  total_taxes_and_charges numeric(21,9) DEFAULT 0,
  loyalty_points integer DEFAULT 0,
  loyalty_amount numeric(21,9) DEFAULT 0,
  redeem_loyalty_points smallint NOT NULL DEFAULT 0,
  loyalty_program_id bigint,   -- -> Loyalty Program
  loyalty_redemption_account_id bigint,   -- -> Account
  loyalty_redemption_cost_center_id bigint,   -- -> Cost Center
  apply_discount_on varchar(140),   -- enum: Grand Total | Net Total
  base_discount_amount numeric(21,9) DEFAULT 0,
  additional_discount_percentage numeric(21,9) DEFAULT 0,
  discount_amount numeric(21,9) DEFAULT 0,
  base_grand_total numeric(21,9) NOT NULL DEFAULT 0,
  base_rounding_adjustment numeric(21,9) DEFAULT 0,
  base_rounded_total numeric(21,9) DEFAULT 0,
  base_in_words text,
  grand_total numeric(21,9) NOT NULL DEFAULT 0,
  rounding_adjustment numeric(21,9) DEFAULT 0,
  rounded_total numeric(21,9) DEFAULT 0,
  in_words text,
  total_advance numeric(21,9) DEFAULT 0,
  outstanding_amount numeric(21,9) DEFAULT 0,
  allocate_advances_automatically smallint NOT NULL DEFAULT 0,
  payment_terms_template_id bigint,   -- -> Payment Terms Template
  cash_bank_account_id bigint,   -- -> Account
  base_paid_amount numeric(21,9) DEFAULT 0,
  paid_amount numeric(21,9) DEFAULT 0,
  base_change_amount numeric(21,9) DEFAULT 0,
  change_amount numeric(21,9) DEFAULT 0,
  account_for_change_amount_id bigint,   -- -> Account
  write_off_amount numeric(21,9) DEFAULT 0,
  base_write_off_amount numeric(21,9) DEFAULT 0,
  write_off_outstanding_amount_automatically smallint NOT NULL DEFAULT 0,
  write_off_account_id bigint,   -- -> Account
  write_off_cost_center_id bigint,   -- -> Cost Center
  tc_name_id bigint,   -- -> Terms and Conditions
  terms text,
  letter_head_id bigint,   -- -> Letter Head
  group_same_items smallint NOT NULL DEFAULT 0,
  language_id bigint,   -- -> Language
  select_print_heading_id bigint,   -- -> Print Heading
  inter_company_invoice_reference_id bigint,   -- -> Purchase Invoice
  customer_group_id bigint,   -- -> Customer Group
  is_discounted smallint NOT NULL DEFAULT 0,
  status varchar(140),   -- enum: Draft | Return | Credit Note Issued | Submitted | Paid | Partly Paid
  debit_to_id bigint NOT NULL,   -- -> Account
  party_account_currency_id bigint,   -- -> Currency
  is_opening varchar(140),   -- enum: No | Yes
  remarks text,
  sales_partner_id bigint,   -- -> Sales Partner
  commission_rate numeric(21,9) DEFAULT 0,   -- denormalised from sales_partner.commission_rate
  total_commission numeric(21,9) DEFAULT 0,
  from_date date,
  to_date date,
  auto_repeat_id bigint,   -- -> Auto Repeat
  against_income_account text,
  is_consolidated smallint NOT NULL DEFAULT 0,
  is_internal_customer smallint NOT NULL DEFAULT 0,   -- denormalised from customer.is_internal_customer
  company_tax_id varchar(140),   -- denormalised from company.tax_id
  unrealized_profit_loss_account_id bigint,   -- -> Account
  represents_company_id bigint,   -- -> Company
  set_target_warehouse_id bigint,   -- -> Warehouse
  is_debit_note smallint NOT NULL DEFAULT 0,
  disable_rounded_total smallint NOT NULL DEFAULT 0,
  additional_discount_account_id bigint,   -- -> Account
  dispatch_address_name_id bigint,   -- -> Address
  dispatch_address text,
  ignore_default_payment_terms_template smallint NOT NULL DEFAULT 0,
  total_billing_hours numeric(21,9) DEFAULT 0,
  amount_eligible_for_commission numeric(21,9) DEFAULT 0,
  subscription_id bigint,   -- -> Subscription
  is_cash_or_non_trade_discount smallint NOT NULL DEFAULT 0,
  incoterm_id bigint,   -- -> Incoterm
  named_place varchar(140),
  only_include_allocated_payments smallint NOT NULL DEFAULT 0,
  use_company_roundoff_cost_center smallint NOT NULL DEFAULT 0,
  update_billed_amount_in_delivery_note smallint NOT NULL DEFAULT 1,
  dont_create_loyalty_points smallint NOT NULL DEFAULT 0,
  coupon_code_id bigint,   -- -> Coupon Code
  update_outstanding_for_self smallint NOT NULL DEFAULT 1,
  utm_medium_id bigint,   -- -> UTM Medium
  utm_content varchar(140),
  utm_campaign_id bigint,   -- -> UTM Campaign
  utm_source_id bigint,   -- -> UTM Source
  company_contact_person_id bigint,   -- -> Contact
  is_created_using_pos smallint NOT NULL DEFAULT 0,
  pos_closing_entry_id bigint,   -- -> POS Closing Entry
  has_subcontracted smallint NOT NULL DEFAULT 0,
  apply_tds smallint NOT NULL DEFAULT 0,
  tax_withholding_group_id bigint,   -- -> Tax Withholding Group
  ignore_tax_withholding_threshold smallint NOT NULL DEFAULT 0,
  override_tax_withholding_entries smallint NOT NULL DEFAULT 0,
  title varchar(140),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

