-- Serial No (master)
CREATE TABLE serial_no (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  serial_no varchar(140) NOT NULL,
  item_code_id bigint NOT NULL,   -- -> Item
  item_name varchar(140),   -- denormalised from item_code.item_name
  description text,   -- denormalised from item_code.description
  item_group_id bigint,   -- -> Item Group
  brand_id bigint,   -- -> Brand
  asset_id bigint,   -- -> Asset
  asset_status varchar(140),   -- enum: Issue | Receipt | Transfer
  location_id bigint,   -- -> Location
  employee_id bigint,   -- -> Employee
  maintenance_status varchar(140),   -- enum: Under Warranty | Out of Warranty | Under AMC | Out of AMC
  warranty_period integer DEFAULT 0,   -- denormalised from item_code.warranty_period
  warranty_expiry_date date,
  amc_expiry_date date,
  company_id bigint NOT NULL,   -- -> Company
  work_order_id bigint,   -- -> Work Order
  warehouse_id bigint,   -- -> Warehouse
  batch_no_id bigint,   -- -> Batch
  purchase_rate numeric(21,9) DEFAULT 0,
  status varchar(140),   -- enum: Active | Inactive | Consumed | Delivered | Expired
  customer_id bigint,   -- -> Customer
  reference_doctype_id bigint,   -- -> DocType
  reference_name varchar(140),   -- polymorphic: target doctype in reference_doctype
  posting_date date,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Share Transfer (transaction)
CREATE TABLE share_transfer (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  transfer_type varchar(140) NOT NULL,   -- enum: Issue | Purchase | Transfer
  date date NOT NULL,
  from_shareholder_id bigint,   -- -> Shareholder
  from_folio_no varchar(140),   -- denormalised from from_shareholder.folio_no
  equity_or_liability_account_id bigint NOT NULL,   -- -> Account
  asset_account_id bigint,   -- -> Account
  to_shareholder_id bigint,   -- -> Shareholder
  to_folio_no varchar(140),   -- denormalised from to_shareholder.folio_no
  share_type_id bigint NOT NULL,   -- -> Share Type
  from_no integer NOT NULL DEFAULT 0,
  rate numeric(21,9) NOT NULL DEFAULT 0,
  no_of_shares integer NOT NULL DEFAULT 0,
  to_no integer NOT NULL DEFAULT 0,
  amount numeric(21,9) DEFAULT 0,
  company_id bigint NOT NULL,   -- -> Company
  remarks text,
  amended_from_id bigint,   -- -> Share Transfer
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Share Type (master)
CREATE TABLE share_type (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  title varchar(140) NOT NULL,
  description text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Shareholder (master)
CREATE TABLE shareholder (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  title varchar(140) NOT NULL,
  naming_series varchar(140),   -- enum: ACC-SH-.YYYY.-
  folio_no varchar(140),
  company_id bigint NOT NULL,   -- -> Company
  is_company smallint NOT NULL DEFAULT 0,
  contact_list text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Shareholder.share_balance line items -> Share Balance
CREATE TABLE shareholder_share_balance (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  shareholder_id bigint NOT NULL,   -- parent -> Shareholder
  line_no integer NOT NULL,   -- was ERPNext `idx`
  share_type_id bigint NOT NULL,   -- -> Share Type
  from_no integer NOT NULL DEFAULT 0,
  rate numeric(21,9) NOT NULL DEFAULT 0,
  no_of_shares integer NOT NULL DEFAULT 0,
  to_no integer NOT NULL DEFAULT 0,
  amount numeric(21,9) NOT NULL DEFAULT 0,
  is_company smallint NOT NULL DEFAULT 0,
  current_state varchar(140),   -- enum: Issued | Purchased
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Shipment (transaction)
CREATE TABLE shipment (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  pickup_from_type varchar(140),   -- enum: Company | Customer | Supplier
  pickup_company_id bigint,   -- -> Company
  pickup_customer_id bigint,   -- -> Customer
  pickup_supplier_id bigint,   -- -> Supplier
  pickup varchar(140),
  pickup_address_name_id bigint NOT NULL,   -- -> Address
  pickup_address text,
  pickup_contact_name_id bigint,   -- -> Contact
  pickup_contact_email varchar(140),
  pickup_contact text,
  delivery_to_type varchar(140),   -- enum: Company | Customer | Supplier
  delivery_company_id bigint,   -- -> Company
  delivery_customer_id bigint,   -- -> Customer
  delivery_supplier_id bigint,   -- -> Supplier
  delivery_to varchar(140),
  delivery_address_name_id bigint NOT NULL,   -- -> Address
  delivery_address text,
  delivery_contact_name_id bigint,   -- -> Contact
  delivery_contact_email varchar(140),
  delivery_contact text,
  parcel_template_id bigint,   -- -> Shipment Parcel Template
  pallets varchar(140),   -- enum: No | Yes
  value_of_goods numeric(21,2) NOT NULL DEFAULT 0,
  pickup_date date NOT NULL,
  pickup_from time(6) NOT NULL,
  pickup_to time(6) NOT NULL,
  shipment_type varchar(140),   -- enum: Goods | Documents
  pickup_type varchar(140),   -- enum: Pickup | Self delivery
  description_of_content text NOT NULL,
  service_provider varchar(140),
  shipment_id varchar(140),
  shipment_amount numeric(21,2) DEFAULT 0,
  status varchar(140),   -- enum: Draft | Submitted | Booked | Cancelled | Completed
  tracking_url text,
  carrier varchar(140),
  carrier_service varchar(140),
  awb_number varchar(140),
  tracking_status varchar(140),   -- enum: In Progress | Delivered | Returned | Lost
  tracking_status_info varchar(140),
  amended_from_id bigint,   -- -> Shipment
  incoterm_id bigint,   -- -> Incoterm
  pickup_contact_person_id bigint,   -- -> User
  total_weight numeric(21,9) DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Shipment Parcel Template (master)
CREATE TABLE shipment_parcel_template (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  length numeric(21,9) NOT NULL DEFAULT 0,
  width numeric(21,9) NOT NULL DEFAULT 0,
  height numeric(21,9) NOT NULL DEFAULT 0,
  weight numeric(21,1) NOT NULL DEFAULT 0,
  parcel_template_name varchar(140) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Shipment.shipment_delivery_note line items -> Shipment Delivery Note
CREATE TABLE shipment_shipment_delivery_note (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  shipment_id bigint NOT NULL,   -- parent -> Shipment
  line_no integer NOT NULL,   -- was ERPNext `idx`
  delivery_note_id bigint NOT NULL,   -- -> Delivery Note
  grand_total numeric(21,9) DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Shipment.shipment_parcel line items -> Shipment Parcel
CREATE TABLE shipment_shipment_parcel (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  shipment_id bigint NOT NULL,   -- parent -> Shipment
  line_no integer NOT NULL,   -- was ERPNext `idx`
  length numeric(21,9) DEFAULT 0,
  width numeric(21,9) DEFAULT 0,
  height numeric(21,9) DEFAULT 0,
  weight numeric(21,1) NOT NULL DEFAULT 0,
  count integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Shipping Rule (master)
CREATE TABLE shipping_rule (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  label varchar(140) NOT NULL,
  disabled smallint NOT NULL DEFAULT 0,
  shipping_rule_type varchar(140),   -- enum: Selling | Buying
  company_id bigint NOT NULL,   -- -> Company
  account_id bigint NOT NULL,   -- -> Account
  cost_center_id bigint,   -- -> Cost Center
  calculate_based_on varchar(140),   -- enum: Fixed | Net Total | Net Weight
  shipping_amount numeric(21,9) DEFAULT 0,
  project_id bigint,   -- -> Project
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Shipping Rule.conditions line items -> Shipping Rule Condition
CREATE TABLE shipping_rule_conditions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  shipping_rule_id bigint NOT NULL,   -- parent -> Shipping Rule
  line_no integer NOT NULL,   -- was ERPNext `idx`
  from_value numeric(21,9) NOT NULL DEFAULT 0,
  to_value numeric(21,9) DEFAULT 0,
  shipping_amount numeric(21,9) NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Shipping Rule.countries line items -> Shipping Rule Country
CREATE TABLE shipping_rule_countries (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  shipping_rule_id bigint NOT NULL,   -- parent -> Shipping Rule
  line_no integer NOT NULL,   -- was ERPNext `idx`
  country_id bigint NOT NULL,   -- -> Country
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Stock Closing Balance (master)
CREATE TABLE stock_closing_balance (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  item_code_id bigint,   -- -> Item
  warehouse_id bigint,   -- -> Warehouse
  posting_date date,
  posting_time time(6),
  posting_datetime timestamp,
  actual_qty numeric(21,9) DEFAULT 0,
  valuation_rate numeric(21,9) DEFAULT 0,
  stock_value numeric(21,9) DEFAULT 0,
  company_id bigint,   -- -> Company
  stock_uom_id bigint,   -- -> UOM
  stock_value_difference numeric(21,9) DEFAULT 0,
  item_name varchar(140),
  item_group_id bigint,   -- -> Item Group
  stock_closing_entry_id bigint,   -- -> Stock Closing Entry
  inventory_dimension_key text,
  batch_no_id bigint,   -- -> Batch
  fifo_queue text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Stock Closing Entry (transaction)
CREATE TABLE stock_closing_entry (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  naming_series varchar(140),   -- enum: CBAL-.#####
  company_id bigint,   -- -> Company
  status varchar(140),   -- enum: Draft | Queued | In Progress | Completed | Failed | Cancelled
  from_date date,
  to_date date,
  amended_from_id bigint,   -- -> Stock Closing Entry
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Stock Entry (transaction)
CREATE TABLE stock_entry (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  naming_series varchar(140) NOT NULL,   -- enum: MAT-STE-.YYYY.-
  stock_entry_type_id bigint NOT NULL,   -- -> Stock Entry Type
  outgoing_stock_entry_id bigint,   -- -> Stock Entry
  source_stock_entry_id bigint,   -- -> Stock Entry
  purpose varchar(140),   -- enum: Material Issue | Material Receipt | Material Transfer | Material Transfer for Manufacture | Material Consumption for Manufacture | Manufacture
  company_id bigint NOT NULL,   -- -> Company
  work_order_id bigint,   -- -> Work Order
  purchase_order_id bigint,   -- -> Purchase Order
  subcontracting_order_id bigint,   -- -> Subcontracting Order
  delivery_note_no_id bigint,   -- -> Delivery Note
  sales_invoice_no_id bigint,   -- -> Sales Invoice
  purchase_receipt_no_id bigint,   -- -> Purchase Receipt
  posting_date date,
  posting_time time(6),
  set_posting_time smallint NOT NULL DEFAULT 0,
  inspection_required smallint NOT NULL DEFAULT 0,
  from_bom smallint NOT NULL DEFAULT 0,
  bom_no_id bigint,   -- -> BOM
  fg_completed_qty numeric(21,9) DEFAULT 0,
  use_multi_level_bom smallint NOT NULL DEFAULT 1,
  from_warehouse_id bigint,   -- -> Warehouse
  source_warehouse_address_id bigint,   -- -> Address
  source_address_display text,
  to_warehouse_id bigint,   -- -> Warehouse
  target_warehouse_address_id bigint,   -- -> Address
  target_address_display text,
  scan_barcode varchar(140),
  total_incoming_value numeric(21,9) DEFAULT 0,
  total_outgoing_value numeric(21,9) DEFAULT 0,
  value_difference numeric(21,9) DEFAULT 0,
  total_additional_costs numeric(21,9) DEFAULT 0,
  supplier_id bigint,   -- -> Supplier
  supplier_name varchar(140),
  supplier_address_id bigint,   -- -> Address
  address_display text,
  select_print_heading_id bigint,   -- -> Print Heading
  letter_head_id bigint,   -- -> Letter Head
  is_opening varchar(140),   -- enum: No | Yes
  project_id bigint,   -- -> Project
  remarks text,
  per_transferred numeric(21,9) DEFAULT 0,
  total_amount numeric(21,9) DEFAULT 0,
  job_card_id bigint,   -- -> Job Card
  amended_from_id bigint,   -- -> Stock Entry
  credit_note_id bigint,   -- -> Journal Entry
  pick_list_id bigint,   -- -> Pick List
  add_to_transit smallint NOT NULL DEFAULT 0,   -- denormalised from stock_entry_type.add_to_transit
  apply_putaway_rule smallint NOT NULL DEFAULT 0,
  is_return smallint NOT NULL DEFAULT 0,
  process_loss_qty numeric(21,9) DEFAULT 0,
  process_loss_percentage numeric(21,9) DEFAULT 0,
  asset_repair_id bigint,   -- -> Asset Repair
  is_additional_transfer_entry smallint NOT NULL DEFAULT 0,
  subcontracting_inward_order_id bigint,   -- -> Subcontracting Inward Order
  cost_center_id bigint,   -- -> Cost Center
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Stock Entry.additional_costs line items -> Landed Cost Taxes and Charges
CREATE TABLE stock_entry_additional_costs (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  stock_entry_id bigint NOT NULL,   -- parent -> Stock Entry
  line_no integer NOT NULL,   -- was ERPNext `idx`
  description text NOT NULL,
  amount numeric(21,9) NOT NULL DEFAULT 0,
  expense_account_id bigint,   -- -> Account
  account_currency_id bigint,   -- -> Currency
  exchange_rate numeric(21,9) DEFAULT 0,
  base_amount numeric(21,9) DEFAULT 0,
  has_corrective_cost smallint NOT NULL DEFAULT 0,
  has_operating_cost smallint NOT NULL DEFAULT 0,
  operation_id varchar(140),
  qty numeric(21,9) DEFAULT 0,
  operating_component varchar(140),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Stock Entry.items line items -> Stock Entry Detail
CREATE TABLE stock_entry_items (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  stock_entry_id bigint NOT NULL,   -- parent -> Stock Entry
  line_no integer NOT NULL,   -- was ERPNext `idx`
  barcode varchar(140),
  s_warehouse_id bigint,   -- -> Warehouse
  t_warehouse_id bigint,   -- -> Warehouse
  item_code_id bigint NOT NULL,   -- -> Item
  item_name varchar(140),
  description text,
  image text,
  qty numeric(21,9) NOT NULL DEFAULT 0,
  basic_rate numeric(21,9) DEFAULT 0,
  basic_amount numeric(21,9) DEFAULT 0,
  additional_cost numeric(21,9) DEFAULT 0,
  amount numeric(21,9) DEFAULT 0,
  valuation_rate numeric(21,9) DEFAULT 0,
  uom_id bigint NOT NULL,   -- -> UOM
  conversion_factor numeric(21,9) NOT NULL DEFAULT 0,
  stock_uom_id bigint NOT NULL,   -- -> UOM
  transfer_qty numeric(21,9) DEFAULT 0,
  retain_sample smallint NOT NULL DEFAULT 0,   -- denormalised from item_code.retain_sample
  sample_quantity integer DEFAULT 0,
  serial_no text,
  batch_no_id bigint,   -- -> Batch
  quality_inspection_id bigint,   -- -> Quality Inspection
  expense_account_id bigint,   -- -> Account
  cost_center_id bigint,   -- -> Cost Center
  allow_zero_valuation_rate smallint NOT NULL DEFAULT 0,
  actual_qty numeric(21,9) DEFAULT 0,
  bom_no_id bigint,   -- -> BOM
  allow_alternative_item smallint NOT NULL DEFAULT 0,
  material_request_id bigint,   -- -> Material Request
  material_request_item_id bigint,   -- -> Material Request Item
  pick_list_item_id bigint,   -- -> Pick List Item
  original_item_id bigint,   -- -> Item
  subcontracted_item_id bigint,   -- -> Item
  against_stock_entry_id bigint,   -- -> Stock Entry
  ste_detail varchar(140),
  transferred_qty numeric(21,9) DEFAULT 0,
  item_group varchar(140),   -- denormalised from item_code.item_group
  reference_purchase_receipt_id bigint,   -- -> Purchase Receipt
  project_id bigint,   -- -> Project
  po_detail varchar(140),
  sco_rm_detail varchar(140),
  set_basic_rate_manually smallint NOT NULL DEFAULT 0,
  putaway_rule_id bigint,   -- -> Putaway Rule
  is_finished_item smallint NOT NULL DEFAULT 0,
  job_card_item varchar(140),
  has_item_scanned smallint NOT NULL DEFAULT 0,
  serial_and_batch_bundle_id bigint,   -- -> Serial and Batch Bundle
  use_serial_batch_fields smallint NOT NULL DEFAULT 0,
  landed_cost_voucher_amount numeric(21,9) DEFAULT 0,
  customer_provided_item_cost numeric(21,9) DEFAULT 0,
  scio_detail varchar(140),
  against_fg_id bigint,   -- -> Subcontracting Inward Order Item
  secondary_item_type varchar(140),   -- enum: Co-Product | By-Product | Scrap | Additional Finished Good
  bom_secondary_item varchar(140),
  is_legacy_scrap_item smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Stock Entry Type (master)
CREATE TABLE stock_entry_type (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  purpose varchar(140) NOT NULL,   -- enum: Material Issue | Material Receipt | Material Transfer | Material Transfer for Manufacture | Material Consumption for Manufacture | Manufacture
  add_to_transit smallint NOT NULL DEFAULT 0,
  is_standard smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Stock Ledger Entry (transaction)
CREATE TABLE stock_ledger_entry (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  item_code_id bigint,   -- -> Item
  serial_no text,
  batch_no varchar(140),
  warehouse_id bigint,   -- -> Warehouse
  posting_date date,
  posting_time time(6),
  voucher_type_id bigint,   -- -> DocType
  voucher_no varchar(140),   -- polymorphic: target doctype in voucher_type
  voucher_detail_no varchar(140),
  actual_qty numeric(21,9) DEFAULT 0,
  incoming_rate numeric(21,9) DEFAULT 0,
  outgoing_rate numeric(21,9) DEFAULT 0,
  stock_uom_id bigint,   -- -> UOM
  qty_after_transaction numeric(21,9) DEFAULT 0,
  valuation_rate numeric(21,9) DEFAULT 0,
  stock_value numeric(21,9) DEFAULT 0,
  stock_value_difference numeric(21,9) DEFAULT 0,
  stock_queue text,
  project_id bigint,   -- -> Project
  company_id bigint,   -- -> Company
  fiscal_year varchar(140),
  is_cancelled smallint NOT NULL DEFAULT 0,
  to_rename smallint NOT NULL DEFAULT 1,
  dependant_sle_voucher_detail_no varchar(140),
  recalculate_rate smallint NOT NULL DEFAULT 0,
  serial_and_batch_bundle_id bigint,   -- -> Serial and Batch Bundle
  has_batch_no smallint NOT NULL DEFAULT 0,   -- denormalised from item_code.has_batch_no
  has_serial_no smallint NOT NULL DEFAULT 0,   -- denormalised from item_code.has_serial_no
  is_adjustment_entry smallint NOT NULL DEFAULT 0,
  auto_created_serial_and_batch_bundle smallint NOT NULL DEFAULT 0,
  posting_datetime timestamp,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Stock Reconciliation (transaction)
CREATE TABLE stock_reconciliation (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
