  item_group_id bigint,   -- -> Item Group
  use_serial_batch_fields smallint NOT NULL DEFAULT 0,
  reconcile_all_serial_batch smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

-- Stock Reservation Entry (transaction)
CREATE TABLE stock_reservation_entry (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  docstatus smallint NOT NULL DEFAULT 0,   -- 0 draft, 1 submitted, 2 cancelled
  item_code_id bigint,   -- -> Item
  warehouse_id bigint,   -- -> Warehouse
  voucher_type varchar(140),   -- enum: Sales Order | Work Order | Subcontracting Inward Order | Production Plan | Subcontracting Order
  voucher_no varchar(140),   -- polymorphic: target doctype in voucher_type
  voucher_detail_no varchar(140),
  stock_uom_id bigint,   -- -> UOM
  project_id bigint,   -- -> Project
  company_id bigint,   -- -> Company
  reserved_qty numeric(21,9) DEFAULT 0,
  status varchar(140),   -- enum: Draft | Partially Reserved | Reserved | Partially Delivered | Partially Used | Delivered
  delivered_qty numeric(21,9) DEFAULT 0,
  amended_from_id bigint,   -- -> Stock Reservation Entry
  available_qty numeric(21,9) DEFAULT 0,
  voucher_qty numeric(21,9) DEFAULT 0,
  has_serial_no smallint NOT NULL DEFAULT 0,
  has_batch_no smallint NOT NULL DEFAULT 0,
  reservation_based_on varchar(140),   -- enum: Qty | Serial and Batch
  from_voucher_type varchar(140),   -- enum: Pick List | Purchase Receipt | Stock Entry | Work Order | Production Plan | Subcontracting Inward Order
  from_voucher_detail_no varchar(140),
  from_voucher_no varchar(140),   -- polymorphic: target doctype in from_voucher_type
  consumed_qty numeric(21,9) DEFAULT 0,
  transferred_qty numeric(21,9) DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

