-- Subscription (master)
CREATE TABLE subscription (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_no varchar(140) NOT NULL UNIQUE,   -- ERPNext `name` business key
  status varchar(140),   -- enum: Trialing | Active | Grace Period | Cancelled | Unpaid | Completed
