  trial_period_end date,
  current_invoice_start date,
  current_invoice_end date,
  next_billing_period_start date,
  next_billing_period_end date,
  days_until_due integer DEFAULT 0,
  cancel_at_period_end smallint NOT NULL DEFAULT 0,
  apply_additional_discount varchar(140),   -- enum: Grand Total | Net Total
  additional_discount_percentage numeric(21,9) DEFAULT 0,
  additional_discount_amount numeric(21,9) DEFAULT 0,
  party_type_id bigint NOT NULL,   -- -> DocType
  party varchar(140) NOT NULL,   -- polymorphic: target doctype in party_type
  sales_tax_template_id bigint,   -- -> Sales Taxes and Charges Template
  purchase_tax_template_id bigint,   -- -> Purchase Taxes and Charges Template
  follow_calendar_months smallint NOT NULL DEFAULT 0,
  generate_new_invoices_past_due_date smallint NOT NULL DEFAULT 0,
  end_date date,
  start_date date,
  cost_center_id bigint,   -- -> Cost Center
  company_id bigint,   -- -> Company
  submit_invoice smallint NOT NULL DEFAULT 1,
  generate_invoice_at varchar(140) NOT NULL,   -- enum: Postpaid (bill at period end) | Prepaid (bill at period start) | Bill N days before period start
  number_of_days integer DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

