  disabled smallint NOT NULL DEFAULT 0,
  warn_rfqs smallint NOT NULL DEFAULT 0,
  warn_pos smallint NOT NULL DEFAULT 0,
  prevent_rfqs smallint NOT NULL DEFAULT 0,
  prevent_pos smallint NOT NULL DEFAULT 0,
  default_currency_id bigint,   -- -> Currency
  default_price_list_id bigint,   -- -> Price List
  payment_terms_id bigint,   -- -> Payment Terms Template
