  website varchar(140),
  supplier_details text,
  is_frozen smallint NOT NULL DEFAULT 0,
  allow_purchase_invoice_creation_without_purchase_order smallint NOT NULL DEFAULT 0,
  allow_purchase_invoice_creation_without_purchase_receipt smallint NOT NULL DEFAULT 0,
  supplier_primary_contact_id bigint,   -- -> Contact
  mobile_no varchar(140),   -- denormalised from supplier_primary_contact.mobile_no
  email_id varchar(140),   -- denormalised from supplier_primary_contact.email_id
