  supplier_primary_address_id bigint,   -- -> Address
  restrict_to_companies smallint NOT NULL DEFAULT 0,
  tax_withholding_group_id bigint,   -- -> Tax Withholding Group
  gender_id bigint,   -- -> Gender
  alias varchar(140),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by bigint,
  updated_by bigint
);

